#!/usr/bin/env bash
set -euo pipefail
SCRIPT_DIR="$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")" && pwd)";source "$SCRIPT_DIR/_common.sh";require_commands curl jq openssl docker
BASE_URL="${1:-http://localhost:14200}";CALLBACK_BASE_URL="${2:-http://localhost:18081}";DURATION_SECONDS="${3:-120}";MINIMUM_CALLBACKS="${4:-300}";CONCURRENCY="${5:-12}";DELAY_MILLISECONDS="${6:-500}";SEED="${7:-20261113}"
((DURATION_SECONDS>=10&&MINIMUM_CALLBACKS>=30&&CONCURRENCY>=2&&CONCURRENCY<=64))||{ echo 'Invalid soak parameters'>&2;exit 1; }
tmp="$(new_temp_dir)";trap 'rm -rf -- "$tmp"' EXIT
sql(){ compose exec -T mysql mysql -ucommerceflow -pcommerceflow-password -Nse "$1" commerceflow 2>/dev/null|tr -d '\r'; }
"$SCRIPT_DIR/verify-merchant-fulfillment.sh" "$BASE_URL"
jar="$tmp/customer.cookies";storefront_login "$BASE_URL" demo@example.com "$jar">/dev/null
order="$(json_request GET "$BASE_URL/api/purchase-orders" "$jar"|jq -c '[.[]|select(.status=="SHIPPED" and .logistics!=null)]|sort_by(.createdAt)|reverse|.[0]')";order_id="$(jq -r '.id//empty'<<<"$order")";[[ -n "$order_id" ]]||{ echo 'No shipped order available'>&2;exit 1; }
projection="$(json_request GET "$BASE_URL/api/purchase-orders/$order_id/logistics" "$jar")";merchant_no="$(jq -r .merchantShipmentNo<<<"$projection")";platform_no="$(jq -r .platformShipmentNo<<<"$projection")"
shipment_id="$(sql "SELECT id FROM shipment_records WHERE order_id=$order_id")";initial_identity="$(sql "SELECT CONCAT(platform_shipment_no,'|',carrier,'|',tracking_number) FROM shipment_records WHERE id=$shipment_id")";before_updates="$(sql "SELECT COUNT(*) FROM order_events WHERE order_id=$order_id AND event_type='LOGISTICS_STATUS_UPDATED'")"
run_id="$(uuid_hex|cut -c1-8)";deadline=$(( $(date +%s)+DURATION_SECONDS ));minimum_per_worker=$(( (MINIMUM_CALLBACKS+CONCURRENCY-1)/CONCURRENCY ));delay_seconds="$(awk "BEGIN{printf \"%.3f\",$DELAY_MILLISECONDS/1000}")"
worker(){ local worker="$1" count=0 status occurred body signature code statuses=(CREATED PICKED_UP IN_TRANSIT AT_STATION OUT_FOR_DELIVERY DELIVERED);RANDOM=$((SEED+worker));while((count<minimum_per_worker||$(date +%s)<deadline));do if((count==0&&worker==0));then status=DELIVERED;else status="${statuses[$((RANDOM%6))]}";fi;occurred="$(date -u -d "@$(( $(date +%s)+(RANDOM%7201)-3600 ))" +%Y-%m-%dT%H:%M:%SZ)";body="$(jq -nc --arg id "SOAK-$run_id-$worker-$count" --arg merchant "$merchant_no" --arg platform "$platform_no" --arg status "$status" --arg location "Concurrent node $worker" --arg description "Randomized out-of-order event $count" --arg occurred "$occurred" '{notificationId:$id,merchantShipmentNo:$merchant,platformShipmentNo:$platform,eventType:"PROGRESS",status:$status,carrier:"STALE-CARRIER-MUST-NOT-WIN",trackingNumber:"STALE-TRACKING-MUST-NOT-WIN",location:$location,description:$description,occurredAt:$occurred}')";signature="$(printf '%s' "$body"|openssl dgst -sha256 -hmac demo-logistics-callback-secret -binary|openssl base64 -A)";code="$(curl -sS -o "$tmp/response-$worker.json" -w '%{http_code}' -H "X-Callback-Signature: $signature" -H 'Content-Type: application/json' --data "$body" "$CALLBACK_BASE_URL/api/logistics-notifications/callback")";[[ "$code" == 200 && "$(jq -r .status "$tmp/response-$worker.json")" == PROCESSED ]]||{ echo "worker $worker callback $count failed: HTTP $code" >"$tmp/failure-$worker";return 1;};count=$((count+1));sleep "$delay_seconds";done;echo "$count">"$tmp/count-$worker"; }
pids=();for((w=0;w<CONCURRENCY;w++));do worker "$w"&pids+=("$!");done;failed=0;for pid in "${pids[@]}";do wait "$pid"||failed=1;done;((failed==0))||{ cat "$tmp"/failure-* 2>/dev/null||true;exit 1; }
sent="$(awk '{s+=$1}END{print s+0}' "$tmp"/count-*)";final_status="$(json_request GET "$BASE_URL/api/purchase-orders/$order_id/logistics" "$jar"|jq -r .status)";[[ "$final_status" == DELIVERED ]]||{ echo "Projection regressed to $final_status">&2;exit 1; }
events="$(sql "SELECT COUNT(*) FROM shipment_events WHERE shipment_id=$shipment_id AND event_id LIKE 'SOAK-$run_id-%'")";notifications="$(sql "SELECT COUNT(*) FROM shipment_notifications WHERE shipment_id=$shipment_id AND notification_id LIKE 'SOAK-$run_id-%' AND processing_status='PROCESSED'")";identity="$(sql "SELECT CONCAT(platform_shipment_no,'|',carrier,'|',tracking_number) FROM shipment_records WHERE id=$shipment_id")";updates=$(( $(sql "SELECT COUNT(*) FROM order_events WHERE order_id=$order_id AND event_type='LOGISTICS_STATUS_UPDATED'")-before_updates ));auto_receive="$(sql "SELECT COUNT(*) FROM scheduled_tasks WHERE task_type='AUTO_RECEIVE' AND task_key='order:$order_id'")"
((events==sent&&notifications==sent))||{ echo "Audit mismatch: sent=$sent events=$events notifications=$notifications">&2;exit 1; };[[ "$identity" == "$initial_identity" ]]||{ echo 'Old callback fields overwrote shipment identity'>&2;exit 1; };((updates>=1&&updates<=6&&auto_receive==1))||{ echo "Unbounded projection side effects: updates=$updates autoReceive=$auto_receive">&2;exit 1; }
echo "Logistics ordering soak passed: $sent concurrent callbacks, final DELIVERED, bounded updates=$updates, immutable identity preserved."
